"use client";

import { Gauge, Rocket, ShieldCheck } from "lucide-react";
import { ProgressOrbit } from "@/components/matos-ui/progress-orbit";

export default function ProgressOrbitDemo() {
  return (
    <div className="grid w-full max-w-[760px] gap-3 sm:grid-cols-3">
      <ProgressOrbit
        size="sm"
        label="Launch"
        description="Checklist"
        value={86}
        icon={<Rocket />}
        milestones={[
          { value: 25, label: "Plan" },
          { value: 60, label: "QA" },
          { value: 90, label: "Ship" },
        ]}
      />

      <ProgressOrbit
        size="sm"
        label="Security"
        description="Identity"
        value={72}
        icon={<ShieldCheck />}
        milestones={[
          { value: 30, label: "MFA" },
          { value: 55, label: "SAML" },
          { value: 80, label: "Audit" },
        ]}
        footer="Milestones light up as your score crosses each threshold."
      />

      <ProgressOrbit
        size="sm"
        label="Quality"
        description="Workspace"
        value={64}
        icon={<Gauge />}
        milestones={[
          { value: 20, label: "Data" },
          { value: 50, label: "Usage" },
          { value: 75, label: "Growth" },
        ]}
      />
    </div>
  );
}
